/**
 * Phase 11 production Node distribution controls.
 *
 * These controls execute the delivered production path: the builder CLI, the
 * exported builder function, the AST rewrite and the graph validation that the
 * builder runs before installation. Nothing here mocks the compiler, the graph
 * or the public entrypoints; every ready assertion reads real generated bytes
 * or real installed modules.
 */
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import {
  cpSync, existsSync, mkdirSync, mkdtempSync, readFileSync, realpathSync, renameSync, rmSync, symlinkSync, unlinkSync, writeFileSync,
} from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { createRequire } from 'node:module';
import test from 'node:test';
import { fileURLToPath, pathToFileURL } from 'node:url';

import {
  BuildFailure, PrerequisiteError, rewriteModuleSpecifiers, validateCommonJsGraph, walkFiles,
} from '../../scripts/phase11/node-emit.mjs';
import { expectedFacadeFiles, loadExportPolicy, NODE_DISTRIBUTION_POLICY } from '../../scripts/phase11/node-facades.mjs';

const REPO_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const BUILDER = path.join(REPO_ROOT, 'scripts', 'phase11', 'build-node-distribution.mjs');
const POLICY_PATH = path.join(REPO_ROOT, 'scripts', 'phase11', 'node-facades.mjs');
const POLICY = NODE_DISTRIBUTION_POLICY;
const ENTRIES = POLICY.publicEntries.map(([subpath, base, runtimeExports]) => ({ subpath, base, runtimeExports }));
const DIST = path.join(REPO_ROOT, 'dist');
const CJS = path.join(DIST, 'cjs');
const NODE = path.join(DIST, 'node');

const toPosix = (value) => value.split(path.sep).join('/');

const state = { builder: null, firstRun: null, secondRun: null, before: null };

test('tracked policy loads without private task files', () => {
  const workspace = createWorkspace('tracked-policy');

  try {
    const result = loadExportPolicy(workspace.root);

    assert.equal(result.entries.length, 6);
    assert.equal(existsSync(path.join(workspace.root, 'tasks')), false);
  } finally {
    workspace.dispose();
  }
});

test('dynamic import edges cannot bypass rewrite or graph validation', () => {
  const workspace = createWorkspace('dynamic-edges');
  const typescript = repoTypeScript();

  try {
    const file = path.join(workspace.root, 'index.cjs');

    writeFileSync(file, "exports.load = () => import('../../outside.js');\n");
    writeFileSync(path.join(workspace.root, 'index.d.cts'), 'export declare const load: unknown;\n');
    assert.equal(validateCommonJsGraph(typescript, workspace.root).ok, false, 'escaping dynamic edge must reject');
    writeFileSync(file, "exports.load = () => import('./target.js'); const literal='./never-rewrite.js';\n");
    const rewritten = rewriteModuleSpecifiers(typescript, file, 'runtime');

    assert.equal(rewritten.rewritten, 1);
    assert.match(readFileSync(file, 'utf8'), /import\('\.\/target.cjs'\)/);
    assert.match(readFileSync(file, 'utf8'), /never-rewrite.js/);
    assert.equal(validateCommonJsGraph(typescript, workspace.root).ok, false, 'missing dynamic target must reject');
    writeFileSync(path.join(workspace.root, 'target.cjs'), 'exports.value=1;\n');
    writeFileSync(path.join(workspace.root, 'target.d.cts'), 'export declare const value: number;\n');
    assert.equal(validateCommonJsGraph(typescript, workspace.root).ok, true);
    writeFileSync(file, 'exports.load = (path) => import(path);\n');
    assert.equal(validateCommonJsGraph(typescript, workspace.root).ok, false, 'nonliteral dynamic edge must reject');
  } finally {
    workspace.dispose();
  }
});

for (const component of ['dist', 'cjs', 'node']) {
  test(`builder rejects linked ${component} without touching outside sentinels`, async () => {
    const workspace = createFixture(`linked-${component}`, { esm: true });
    const build = (await import(pathToFileURL(BUILDER).href)).buildNodeDistribution;

    try {
      const outside = path.join(workspace.root, 'outside');

      mkdirSync(outside);

      if (component === 'dist') {
        rmSync(outside, { recursive: true });
        renameSync(path.join(workspace.root, 'dist'), outside);
      }

      const target = component === 'dist' ? 'dist' : `dist/${component}`;
      const sentinel = path.join(outside, 'sentinel.cjs');

      writeFileSync(sentinel, 'outside-owned-test-sentinel');
      workspace.link(outside, target);
      await assert.rejects(build({ repoRoot: workspace.root }), /linked|symbolic|junction/i);
      assert.equal(readFileSync(sentinel, 'utf8'), 'outside-owned-test-sentinel');
    } finally {
      workspace.dispose();
    }
  });
}

function hashFile(file) {
  return createHash('sha256').update(readFileSync(file)).digest('hex');
}

function hashTree(root, filter) {
  const files = walkFiles(root).filter((file) => filter === undefined || filter(toPosix(path.relative(root, file))));
  const hash = createHash('sha256');

  for (const file of files) {
    hash.update(toPosix(path.relative(root, file)));
    hash.update('\0');
    hash.update(readFileSync(file));
    hash.update('\0');
  }

  return { files: files.length, digest: hash.digest('hex') };
}

function originalEsmDigest() {
  return hashTree(DIST, (relative) => !relative.startsWith('cjs/') && !relative.startsWith('node/'));
}

function nodeOutputDigests() {
  const rows = {};

  for (const root of [CJS, NODE]) {
    for (const file of walkFiles(root)) rows[toPosix(path.relative(DIST, file))] = hashFile(file);
  }

  return rows;
}

function runCli(args) {
  const result = spawnSync(process.execPath, [BUILDER, ...args], {
    cwd: REPO_ROOT, encoding: 'utf8', timeout: 600000, maxBuffer: 16 * 1024 * 1024,
  });

  assert.equal(result.error, undefined, `builder did not run: ${result.error === undefined ? '' : result.error.message}`);

  return { status: result.status, stdout: result.stdout ?? '', stderr: result.stderr ?? '' };
}

function repoTypeScript() {
  return createRequire(path.join(REPO_ROOT, 'package.json'))('typescript');
}

/** OS-temp workspace with a pre-ledgered link list and verified cleanup. */
function createWorkspace(label) {
  const root = mkdtempSync(path.join(os.tmpdir(), `phase11-test-${label}-`));
  const links = [];
  const tempRoot = path.resolve(os.tmpdir());

  return {
    root,
    link(target, relative) {
      const at = path.resolve(root, relative);
      const relativeToRoot = path.relative(root, at);

      assert.ok(relativeToRoot !== '' && !relativeToRoot.startsWith('..') && !path.isAbsolute(relativeToRoot), `link outside workspace: ${at}`);
      assert.ok(!links.includes(at), `link already tracked: ${at}`);
      links.push(at);
      mkdirSync(path.dirname(at), { recursive: true });
      symlinkSync(realpathSync(target), at, 'junction');

      return at;
    },
    dispose() {
      for (const link of links) {
        try {
          unlinkSync(link);
        } catch {
          // A link already removed by the test is fine; the root check below is authoritative.
        }
      }

      const relativeToTemp = path.relative(tempRoot, root);

      assert.ok(relativeToTemp.startsWith('phase11-test-'), `refusing to remove ${root}`);
      rmSync(root, { recursive: true, force: true });
      assert.equal(existsSync(root), false, `workspace survived cleanup: ${root}`);
    },
  };
}

function writeEsmPlaceholders(root) {
  for (const entry of ENTRIES) {
    for (const extension of ['.js', '.d.ts']) {
      const file = path.join(root, 'dist', `${entry.base}${extension}`);

      mkdirSync(path.dirname(file), { recursive: true });
      writeFileSync(file, 'placeholder\n');
    }
  }

  mkdirSync(path.join(root, 'dist', 'cli'), { recursive: true });
  writeFileSync(path.join(root, 'dist', 'cli', 'index.js'), 'placeholder\n');
}

function createFixture(label, settings) {
  const workspace = createWorkspace(label);

  cpSync(path.join(REPO_ROOT, 'src'), path.join(workspace.root, 'src'), { recursive: true });
  writeFileSync(path.join(workspace.root, 'package.json'), `${JSON.stringify({ name: `phase11-${label}`, version: '0.0.0', private: true, type: 'module' }, null, 2)}\n`);
  workspace.link(path.join(REPO_ROOT, 'node_modules'), 'node_modules');

  if (settings?.esm === true) writeEsmPlaceholders(workspace.root);

  if (settings?.broken === true) writeFileSync(path.join(workspace.root, 'src', 'zz-broken.ts'), 'export const broken: = 1;\n');

  if (settings?.sentinels === true) {
    for (const relative of ['dist/cjs/sentinel.cjs', 'dist/node/sentinel.js']) {
      const file = path.join(workspace.root, relative);

      mkdirSync(path.dirname(file), { recursive: true });
      writeFileSync(file, 'sentinel\n');
    }
  }

  return workspace;
}

/* ------------------------------------------------------------------ *
 * CLI surface
 * ------------------------------------------------------------------ */

test('CLI: --help exits 0 and usage errors exit 2', () => {
  const help = runCli(['--help']);

  assert.equal(help.status, 0, help.stderr);
  assert.match(help.stdout, /Usage: node scripts\/phase11\/build-node-distribution\.mjs/);
  assert.match(help.stdout, /3 blocked prerequisite/);

  const unknown = runCli(['--not-a-flag']);

  assert.equal(unknown.status, 2, unknown.stderr);
  assert.match(unknown.stderr, /unknown argument: --not-a-flag/);

  const missingValue = runCli(['--results']);

  assert.equal(missingValue.status, 2, missingValue.stderr);
  assert.match(missingValue.stderr, /--results requires a file path/);
});

test('importing the builder never executes the CLI', async () => {
  const before = existsSync(CJS) ? nodeOutputDigests() : null;
  const esmBefore = originalEsmDigest();
  const module = await import(pathToFileURL(BUILDER).href);

  assert.ok(module.buildNodeDistribution instanceof Function, 'buildNodeDistribution export missing');
  assert.ok(module.runSelfTest instanceof Function, 'runSelfTest export missing');
  assert.ok(module.main instanceof Function, 'main export missing');
  assert.deepEqual(existsSync(CJS) ? nodeOutputDigests() : null, before);
  assert.deepEqual(originalEsmDigest(), esmBefore);
  state.builder = module;
});

test('--self-test reports controls-only evidence', () => {
  const run = runCli(['--self-test']);

  assert.equal(run.status, 0, run.stderr);
  const report = JSON.parse(run.stdout);

  assert.equal(report.status, 'CONTROLS-PASS');
  assert.equal(report.controlsOnly, true);
  assert.equal(report.controls.length, 6);
  assert.ok(report.controls.every((control) => control.passed === true));
  assert.deepEqual(report.controls.map((control) => control.name), [
    'export-policy-shape',
    'ast-runtime-rewrite-preserves-ordinary-strings',
    'ast-declaration-rewrite',
    'graph-validation-rejects-poisoned-edge',
    'missing-original-esm-blocks',
    'facade-inventory-six-entries',
  ]);
});

/* ------------------------------------------------------------------ *
 * Production build
 * ------------------------------------------------------------------ */

test('production build: two runs are byte-identical and leave original ESM intact', async () => {
  for (const entry of ENTRIES) {
    for (const extension of ['.js', '.d.ts']) {
      assert.ok(existsSync(path.join(DIST, `${entry.base}${extension}`)), `missing dist/${entry.base}${extension}; run npm run build before this test`);
    }
  }

  assert.ok(existsSync(path.join(DIST, 'cli', 'index.js')), 'missing dist/cli/index.js');

  const cliSha = hashFile(path.join(DIST, 'cli', 'index.js'));
  const indexSha = hashFile(path.join(DIST, 'index.js'));
  const esmBefore = originalEsmDigest();
  const srcBefore = hashTree(path.join(REPO_ROOT, 'src'));

  const first = runCli([]);

  assert.equal(first.status, 0, first.stderr);
  state.firstRun = JSON.parse(first.stdout);
  assert.equal(state.firstRun.status, 'PASS');
  const firstDigests = nodeOutputDigests();

  // Second build through the exported builder API: a different entry path must
  // produce the same bytes as the CLI path.
  const report = await state.builder.buildNodeDistribution({ repoRoot: REPO_ROOT });

  state.secondRun = report;
  const secondDigests = nodeOutputDigests();

  assert.deepEqual(secondDigests, firstDigests, 'two builds differ byte-for-byte');
  assert.deepEqual(originalEsmDigest(), esmBefore, 'original ESM dist changed');
  assert.equal(hashFile(path.join(DIST, 'cli', 'index.js')), cliSha, 'ESM CLI changed');
  assert.equal(hashFile(path.join(DIST, 'index.js')), indexSha, 'ESM entry changed');
  assert.deepEqual(hashTree(path.join(REPO_ROOT, 'src')), srcBefore, 'builder mutated src/');
  assert.equal(report.policy.sha256, hashFile(POLICY_PATH), 'builder read a different export policy');

  assert.equal(report.status, 'PASS');
  assert.equal(report.graph.ok, true);
  assert.equal(report.graph.unresolved, 0);
  assert.equal(report.graph.stale, 0);
  assert.equal(report.graph.escapes, 0);
  assert.equal(report.graph.esmSyntax, 0);
  assert.equal(report.graph.externalRuntimeSpecifiers, 0);
  assert.ok(report.graph.runtimeEdges > 0);
  assert.ok(report.graph.declarationEdges > 0);
  assert.equal(report.integrity.esmUnchanged, true);
  assert.equal(report.integrity.absolutePathLeaks, 0);
  assert.equal(report.cleanup.removed, true);
  assert.equal(report.cleanup.linksUnlinked, 1);

  const expectedModules = walkFiles(path.join(REPO_ROOT, 'src'))
    .filter((file) => file.endsWith('.ts') && !toPosix(path.relative(path.join(REPO_ROOT, 'src'), file)).startsWith('cli/'));

  assert.equal(report.counts.cjsModules, expectedModules.length);
  assert.equal(report.counts.cjsDeclarations, expectedModules.length);
  assert.equal(report.counts.facadeModules, 6);
  assert.equal(report.counts.facadeDeclarations, 6);
  assert.equal(report.source.modules, expectedModules.length);
  assert.equal(report.source.excludedCliModules, 4);
  assert.equal(report.outputs.length, expectedModules.length * 2 + 12);
  assert.ok(report.outputs.every((output) => /^[0-9a-f]{64}$/.test(output.sha256) && output.bytes > 0));
  assert.ok(report.outputs.some((output) => output.path === 'dist/cjs/index.cjs'));
  assert.ok(report.outputs.some((output) => output.path === 'dist/node/index.js'));
  assert.ok(report.entries.every((entry) => entry.identity.identical === true), JSON.stringify(report.entries));
});

test('graph: no CommonJS edge points at an original ESM module', () => {
  const typescript = repoTypeScript();
  const report = validateCommonJsGraph(typescript, CJS);
  const files = walkFiles(CJS).map((file) => toPosix(path.relative(CJS, file)));

  assert.equal(report.ok, true, JSON.stringify(report.stale));
  assert.equal(report.stale.length, 0);
  assert.equal(report.unresolved.length, 0);
  assert.ok(files.every((file) => file.endsWith('.cjs') || file.endsWith('.d.cts')), 'unexpected file in dist/cjs');
  assert.ok(files.includes('internal/crypto.cjs'), 'nested runtime module missing');
  assert.ok(files.includes('providers/index.d.cts'), 'nested declaration module missing');
  assert.ok(readFileSync(path.join(CJS, 'index.cjs'), 'utf8').includes('require("./core.cjs")'));
  assert.ok(!readFileSync(path.join(CJS, 'index.cjs'), 'utf8').includes('require("./core.js")'));
  assert.ok(readFileSync(path.join(CJS, 'providers', 'index.d.cts'), 'utf8').includes("'./stripe.cjs'"));
});

test('facades: exactly six modules exporting exactly the frozen runtime names', async () => {
  const require = createRequire(path.join(REPO_ROOT, 'package.json'));
  const files = walkFiles(NODE).map((file) => toPosix(path.relative(NODE, file)));

  assert.deepEqual(files.sort(), expectedFacadeFiles(ENTRIES));
  assert.equal(files.length, 12);

  for (const entry of ENTRIES) {
    const facade = await import(pathToFileURL(path.join(NODE, `${entry.base}.js`)).href);
    const commonjs = require(path.join(CJS, `${entry.base}.cjs`));
    const names = Object.keys(facade).sort();

    assert.deepEqual(names, [...entry.runtimeExports].sort(), `${entry.subpath} facade exports`);

    for (const name of entry.runtimeExports) {
      assert.equal(facade[name], commonjs[name], `${entry.subpath} ${name} is not the CommonJS reference`);
    }
  }
});

test('identity: import and require share functions, the error class and diagnostics', async () => {
  const require = createRequire(path.join(REPO_ROOT, 'package.json'));
  const commonjs = require(path.join(CJS, 'index.cjs'));
  const errors = require(path.join(CJS, 'errors.cjs'));
  const diagnostics = require(path.join(CJS, 'diagnostics', 'index.cjs'));
  const esm = await import(pathToFileURL(path.join(NODE, 'index.js')).href);
  const esmDiagnostics = await import(pathToFileURL(path.join(NODE, 'diagnostics', 'index.js')).href);

  assert.equal(commonjs.HooklatchError, errors.HooklatchError);
  assert.equal(esm.HooklatchError, commonjs.HooklatchError);
  assert.equal(esmDiagnostics.diagnose, diagnostics.diagnose);

  assert.throws(
    () => commonjs.createVerifier({ provider: 'not-a-provider', secrets: ['synthetic'] }),
    (error) => error instanceof commonjs.HooklatchError && error instanceof esm.HooklatchError && error.code === 'unknown-provider',
  );

  const crossFormat = new esm.HooklatchError('missing-secrets', 'Synthetic message.');
  const diagnostic = diagnostics.diagnose(crossFormat);

  assert.equal(diagnostic.code, 'missing-secrets');
  assert.equal(diagnostic.kind, 'setup');
  assert.equal(esmDiagnostics.diagnose(crossFormat).code, 'missing-secrets');

  const result = await commonjs.verify({ rawBody: new TextEncoder().encode('{}'), headers: [] }, { provider: 'stripe', secrets: ['synthetic'] });

  assert.equal(result.ok, false);
  assert.equal(result.reason, 'missing-signature');

  await assert.rejects(
    esm.verifyRequest({}, { provider: 'stripe', secrets: ['synthetic'] }),
    (error) => error instanceof commonjs.HooklatchError && error.code === 'invalid-input',
  );
});

test('generated output never embeds an authoring or staging path', () => {
  const forbidden = [toPosix(REPO_ROOT), REPO_ROOT, path.resolve(os.tmpdir())];

  for (const root of [CJS, NODE]) {
    for (const file of walkFiles(root)) {
      const text = readFileSync(file, 'utf8');

      for (const prefix of forbidden) assert.equal(text.includes(prefix), false, `${toPosix(path.relative(REPO_ROOT, file))} embeds ${prefix}`);
    }
  }
});

/* ------------------------------------------------------------------ *
 * Poisoned graph controls (isolated temp copies)
 * ------------------------------------------------------------------ */

test('graph validation rejects a poisoned runtime edge, a missing target and a stale declaration edge', () => {
  const typescript = repoTypeScript();
  const workspace = createWorkspace('poison');

  try {
    const clean = path.join(workspace.root, 'clean');

    cpSync(CJS, clean, { recursive: true });
    assert.equal(validateCommonJsGraph(typescript, clean).ok, true);

    const staleRuntime = path.join(workspace.root, 'stale-runtime');

    cpSync(CJS, staleRuntime, { recursive: true });
    const runtimeFile = path.join(staleRuntime, 'index.cjs');

    writeFileSync(runtimeFile, readFileSync(runtimeFile, 'utf8').replace('require("./core.cjs")', 'require("./core.js")'));
    const staleReport = validateCommonJsGraph(typescript, staleRuntime);

    assert.equal(staleReport.ok, false);
    assert.deepEqual(staleReport.stale, [{ file: 'index.cjs', specifier: './core.js' }]);

    const missingTarget = path.join(workspace.root, 'missing-target');

    cpSync(CJS, missingTarget, { recursive: true });
    rmSync(path.join(missingTarget, 'providers', 'stripe.cjs'));
    const missingReport = validateCommonJsGraph(typescript, missingTarget);

    assert.equal(missingReport.ok, false);
    assert.ok(missingReport.unresolved.some((edge) => edge.target === 'providers/stripe.cjs'), JSON.stringify(missingReport.unresolved));

    const staleDeclaration = path.join(workspace.root, 'stale-declaration');

    cpSync(CJS, staleDeclaration, { recursive: true });
    const declarationFile = path.join(staleDeclaration, 'index.d.cts');

    writeFileSync(declarationFile, readFileSync(declarationFile, 'utf8').replace("'./core.cjs'", "'./core.js'"));
    const declarationReport = validateCommonJsGraph(typescript, staleDeclaration);

    assert.equal(declarationReport.ok, false);
    assert.deepEqual(declarationReport.stale, [{ file: 'index.d.cts', specifier: './core.js' }]);
  } finally {
    workspace.dispose();
  }
});

/* ------------------------------------------------------------------ *
 * AST-bound rewrite controls
 * ------------------------------------------------------------------ */

test('rewrite: only AST module specifiers change, ordinary strings survive', () => {
  const typescript = repoTypeScript();
  const workspace = createWorkspace('rewrite');

  try {
    const runtimeFile = path.join(workspace.root, 'control.cjs');

    writeFileSync(runtimeFile, [
      '"use strict";',
      "const marker = './never-rewrite.js';",
      'const text = "require(\'../never/rewrite.js\')";',
      "const core = require('./core.js');",
      "const descriptor = require('../providers/stripe.js');",
      "const crypto = require('node:crypto');",
      'module.exports = { marker, text, core, descriptor, crypto };',
      '',
    ].join('\n'));

    const runtime = rewriteModuleSpecifiers(typescript, runtimeFile, 'runtime');
    const runtimeSource = readFileSync(runtimeFile, 'utf8');

    assert.equal(runtime.rewritten, 2);
    assert.ok(runtimeSource.includes("const marker = './never-rewrite.js';"));
    assert.ok(runtimeSource.includes("require('../never/rewrite.js')"), runtimeSource);
    assert.ok(runtimeSource.includes("require('./core.cjs')"));
    assert.ok(runtimeSource.includes("require('../providers/stripe.cjs')"));
    assert.ok(runtimeSource.includes("require('node:crypto')"));

    const declarationFile = path.join(workspace.root, 'control.d.cts');

    writeFileSync(declarationFile, [
      "import type { A } from './types.js';",
      "export * from '../providers/index.js';",
      "declare module 'express-serve-static-core' { interface Request { marker?: A } }",
      "export declare const value: import('./types.js').A;",
      '',
    ].join('\n'));

    const declaration = rewriteModuleSpecifiers(typescript, declarationFile, 'declaration');
    const declarationSource = readFileSync(declarationFile, 'utf8');

    assert.equal(declaration.rewritten, 3);
    assert.ok(declarationSource.includes("from './types.cjs'"));
    assert.ok(declarationSource.includes("from '../providers/index.cjs'"));
    assert.ok(declarationSource.includes("import('./types.cjs')"));
    assert.ok(declarationSource.includes("declare module 'express-serve-static-core'"));
  } finally {
    workspace.dispose();
  }
});

