test('missing original ESM output blocks with exit-class prerequisite and no output', async () => {
  const build = state.builder.buildNodeDistribution;
  const workspace = createFixture('missing-esm', {});

  try {
    await assert.rejects(build({ repoRoot: workspace.root }), (error) => error instanceof PrerequisiteError && /run npm run build first/.test(error.message));
    assert.equal(existsSync(path.join(workspace.root, 'dist', 'cjs')), false);
    assert.equal(existsSync(path.join(workspace.root, 'dist', 'node')), false);
  } finally {
    workspace.dispose();
  }
});

test('missing source tree blocks without creating output', async () => {
  const workspace = createFixture('missing-source', {});

  try {
    rmSync(path.join(workspace.root, 'src'), { recursive: true, force: true });
    await assert.rejects(state.builder.buildNodeDistribution({ repoRoot: workspace.root }), (error) => error instanceof PrerequisiteError);
    assert.equal(existsSync(path.join(workspace.root, 'dist', 'cjs')), false);
  } finally {
    workspace.dispose();
  }
});

test('a partial/failed emit fails without replacing existing output', async () => {
  const workspace = createFixture('broken-source', { esm: true, broken: true, sentinels: true });

  try {
    await assert.rejects(
      state.builder.buildNodeDistribution({ repoRoot: workspace.root }),
      (error) => error instanceof BuildFailure && /CommonJS emit failed/.test(error.message),
    );

    assert.equal(readFileSync(path.join(workspace.root, 'dist', 'cjs', 'sentinel.cjs'), 'utf8'), 'sentinel\n');
    assert.equal(readFileSync(path.join(workspace.root, 'dist', 'node', 'sentinel.js'), 'utf8'), 'sentinel\n');
    assert.deepEqual(walkFiles(path.join(workspace.root, 'dist', 'cjs')).map((file) => path.basename(file)), ['sentinel.cjs']);
    assert.deepEqual(walkFiles(path.join(workspace.root, 'dist', 'node')).map((file) => path.basename(file)), ['sentinel.js']);
  } finally {
    workspace.dispose();
  }
});

/* ------------------------------------------------------------------ *
 * Packed builder candidate: NodeNext declaration resolution
 * ------------------------------------------------------------------ */

test('packed candidate resolves both .mts and .cts consumers with skipLibCheck false', () => {
  const workspace = createWorkspace('types');
  const typescript = path.join(REPO_ROOT, 'node_modules', 'typescript', 'bin', 'tsc');
  const packageRoot = path.join(workspace.root, 'node_modules', 'hooklatch');

  try {
    mkdirSync(packageRoot, { recursive: true });
    cpSync(DIST, path.join(packageRoot, 'dist'), { recursive: true });
    writeFileSync(path.join(packageRoot, 'package.json'), `${JSON.stringify({
      name: 'hooklatch',
      version: '1.0.0',
      type: POLICY.type,
      main: POLICY.main,
      types: POLICY.types,
      bin: POLICY.bin,
      exports: POLICY.exports,
      engines: POLICY.engines,
      peerDependencies: POLICY.peerDependencies,
      peerDependenciesMeta: POLICY.peerDependenciesMeta,
    }, null, 2)}\n`);

    for (const dependency of ['@types/express', '@types/node', 'express', 'hono']) {
      workspace.link(path.join(REPO_ROOT, 'node_modules', dependency), path.join('node_modules', dependency));
    }

    for (const entry of ENTRIES) {
      const target = POLICY.exports[entry.subpath].node.import.default;

      assert.ok(existsSync(path.join(packageRoot, target)), `policy target missing: ${target}`);
      assert.ok(existsSync(path.join(packageRoot, POLICY.exports[entry.subpath].node.require.default)), `policy target missing for ${entry.subpath}`);
      assert.ok(existsSync(path.join(packageRoot, POLICY.exports[entry.subpath].node.import.types)), `declaration target missing for ${entry.subpath}`);
    }

    writeFileSync(path.join(workspace.root, 'consumer.mts'), [
      "import { verify, verifyRequest, createVerifier, HooklatchError, type VerifyOptions, type VerificationResult } from 'hooklatch';",
      "import { diagnose } from 'hooklatch/diagnostics';",
      "import { createWebhookMiddleware } from 'hooklatch/express';",
      '',
      "const options: VerifyOptions = { provider: 'stripe', secrets: ['synthetic'] };",
      'const verifier = createVerifier(options);',
      'const middleware = createWebhookMiddleware(options);',
      'void verify;',
      'void verifyRequest;',
      'void middleware;',
      'void diagnose(new HooklatchError("invalid-input", "Synthetic."));',
      'const result: Promise<VerificationResult> = verifier({ rawBody: new Uint8Array(), headers: [] });',
      'void result;',
      '',
    ].join('\n'));
    writeFileSync(path.join(workspace.root, 'consumer.cts'), [
      "import hooklatch = require('hooklatch');",
      "import diagnostics = require('hooklatch/diagnostics');",
      '',
      "const verifier: (request: { rawBody: Uint8Array; headers: [string, string][] }) => Promise<hooklatch.VerificationResult> = hooklatch.createVerifier({ provider: 'stripe', secrets: ['synthetic'] });",
      'void verifier;',
      'void diagnostics.diagnose(new hooklatch.HooklatchError("missing-secrets", "Synthetic."));',
      '',
    ].join('\n'));
    writeFileSync(path.join(workspace.root, 'tsconfig.json'), `${JSON.stringify({
      compilerOptions: {
        target: 'ES2022', module: 'NodeNext', moduleResolution: 'NodeNext', strict: true,
        noEmit: true, skipLibCheck: false, types: [], lib: ['ES2022', 'DOM'],
      },
      include: ['consumer.mts', 'consumer.cts'],
    }, null, 2)}\n`);

    const compile = spawnSync(process.execPath, [typescript, '-p', path.join(workspace.root, 'tsconfig.json')], {
      cwd: workspace.root, encoding: 'utf8', timeout: 300000, maxBuffer: 8 * 1024 * 1024,
    });

    assert.equal(compile.error, undefined, 'consumer typecheck did not run');
    assert.equal(compile.status, 0, `${compile.stdout}${compile.stderr}`);
  } finally {
    workspace.dispose();
  }
});
